const app=document.querySelector('#app');
function seoulDate(value=new Date()){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value).filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}-${parts.day}`}
function daysInMonth(month){const [year,number]=month.split('-').map(Number);return new Date(Date.UTC(year,number,0)).getUTCDate()}
function shiftMonth(month,delta){const [year,number]=month.split('-').map(Number);const absolute=year*12+(number-1)+delta;return `${Math.floor(absolute/12)}-${String((absolute%12+12)%12+1).padStart(2,'0')}`}
let state={token:localStorage.token||'',user:null,page:'tasks',tasks:[],selectedTaskId:null,month:seoulDate().slice(0,7),taskFilters:{status:'',q:'',received_from:'',received_to:'',due_from:'',due_to:'',assignee_id:'',page:1,page_size:20},statisticsFilters:{received_from:'',received_to:'',assignee_id:''}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&gt;','>':'&lt;','"':'&quot;',"'":'&#39;'}[c]));
const statusName=s=>({RECEIVED:'접수',IN_PROGRESS:'진행중',COMPLETED:'처리'}[s]||s);
async function api(path,options={}){const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(state.token?{Authorization:`Bearer ${state.token}`}:{}),...(options.headers||{})};const r=await fetch(path,{...options,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.detail||'요청 처리에 실패했습니다.');return d}
async function downloadTaskExport(filters){const params=new URLSearchParams();for(const key of ['status','q','received_from','received_to','due_from','due_to','assignee_id'])if(filters[key])params.set(key,filters[key]);const response=await fetch('/api/tasks/export.xlsx?'+params,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.detail||'엑셀 파일을 만들지 못했습니다.')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='shared-work-calendar-tasks.xlsx';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function shell(content){const admin=state.user?.role==='ADMIN';return `<div class="shell"><header class="top"><div><h1>공유 업무 캘린더</h1><div class="muted">${esc(state.user.name)} · ${admin?'관리자':'일반 이용자'}</div></div><button class="button" id="logout">로그아웃</button></header><nav class="nav"><button data-page="tasks" class="${state.page==='tasks'?'active':''}">${admin?'전체 업무':'내 업무'}</button><button data-page="calendar" class="${state.page==='calendar'?'active':''}">캘린더</button><button data-page="completedCalendar" class="${state.page==='completedCalendar'?'active':''}">처리 리포트</button><button data-page="statistics" class="${state.page==='statistics'?'active':''}">통계</button><button data-page="notifications" class="${state.page==='notifications'?'active':''}">알림</button><button data-page="new" class="${state.page==='new'?'active':''}">업무 등록</button>${admin?`<button data-page="users" class="${state.page==='users'?'active':''}">사용자 관리</button><button data-page="masters" class="${state.page==='masters'?'active':''}">요청 정보 관리</button><button data-page="audit" class="${state.page==='audit'?'active':''}">감사 로그</button>`:''}</nav>${content}</div>`}
function bindShell(){document.querySelector('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('token');state.token='';state.user=null;render()};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()})}
function taskCard(t){return `<button type="button" class="task ${t.status} task-open" data-task-id="${t.id}" aria-label="업무 상세 열기: ${esc(t.description.slice(0,60))}"><h3>${esc(t.description).slice(0,60)}</h3><div class="muted">${statusName(t.status)} · ${esc(t.contact.name)} · ${esc(t.contact.organization)}</div><div class="muted">처리자: ${t.assignees.map(a=>esc(a.name)).join(', ')} · 접수일 ${esc(t.received_date)}${t.due_date?` · 마감일 ${esc(t.due_date)}`:''}${t.completed_date?` · 처리일 ${esc(t.completed_date)}`:''}</div><span class="open-hint">상세/수정 열기</span></button>`}
function boardTaskCard(t){return `<button type="button" class="board-task ${t.status}" data-task-id="${t.id}" aria-label="업무 상세 열기: ${esc(t.description.slice(0,60))}"><span class="board-task-title">${esc(t.description).slice(0,48)}</span><span class="board-task-meta">${esc(t.contact.name)} · ${esc(t.contact.organization)}</span><span class="board-task-date">접수 ${esc(t.received_date)}${t.due_date?` · 마감 ${esc(t.due_date)}`:''}</span></button>`}
const BOARD_PAGE_SIZE=3;
const boardStatusOrder=[['IN_PROGRESS','진행중'],['RECEIVED','접수'],['COMPLETED','처리완료']];
function boardQuery(userId,status,page){const params=new URLSearchParams({page:String(page),page_size:String(BOARD_PAGE_SIZE),assignee_id:String(userId),status});for(const key of ['q','received_from','received_to','due_from','due_to'])if(state.taskFilters[key])params.set(key,state.taskFilters[key]);return '/api/tasks?'+params}
async function loadUserBoard(assignees){const users=state.taskFilters.assignee_id?assignees.filter(user=>String(user.id)===String(state.taskFilters.assignee_id)):assignees;const activeStatuses=state.taskFilters.status?[state.taskFilters.status]:boardStatusOrder.map(([status])=>status);const requests=[];for(const user of users)for(const status of activeStatuses)requests.push(api(boardQuery(user.id,status,1)).then(result=>({userId:user.id,status,result})));const groups=await Promise.all(requests);return users.map(user=>{const byStatus={};for(const {userId,status,result} of groups)if(userId===user.id)byStatus[status]=result;return {...user,groups:byStatus}}).filter(user=>Object.values(user.groups).some(group=>group.pagination.total>0))}
function userTaskBoard(users){if(!users.length)return '<p class="muted">표시할 업무가 없습니다.</p>';return `<div class="user-board" aria-label="이용자별 업무 보드">${users.map(user=>{const total=Object.values(user.groups).reduce((sum,group)=>sum+group.pagination.total,0);return `<article class="user-lane" data-user-lane="${user.id}"><header class="user-lane-header"><span class="user-avatar">${esc(user.name).slice(0,1)}</span><div><h3>${esc(user.name)}</h3><p>${esc(user.login_id)} · ${total}건</p></div><button type="button" class="show-user-all" data-user-id="${user.id}">전체 보기</button></header>${boardStatusOrder.map(([status,label])=>{const group=user.groups[status]||{items:[],pagination:{total:0,page:1,total_pages:1}};const more=group.pagination.page<group.pagination.total_pages;return `<section class="status-rail ${status}" data-status="${status}"><button type="button" class="status-rail-title status-filter" data-user-id="${user.id}" data-status="${status}" aria-pressed="false"><span>${label}</span><b>${group.pagination.total}</b><i>내역 보기</i></button><div class="status-track" data-user-id="${user.id}" data-status="${status}" data-page="${group.pagination.page}" data-total-pages="${group.pagination.total_pages}" data-loading="false">${group.items.map(boardTaskCard).join('')||'<span class="empty-status">업무 없음</span>'}${more?'<button type="button" class="board-load-sentinel" aria-label="오른쪽으로 넘겨 다음 업무 불러오기">더 보기 ›</button>':''}</div></section>`}).join('')}</article>`}).join('')}</div>`}
async function loadMoreBoardTasks(track){if(track.dataset.loading==='true'||Number(track.dataset.page)>=Number(track.dataset.totalPages))return;track.dataset.loading='true';const sentinel=track.querySelector('.board-load-sentinel');if(sentinel)sentinel.textContent='불러오는 중…';try{const nextPage=Number(track.dataset.page)+1;const result=await api(boardQuery(track.dataset.userId,track.dataset.status,nextPage));const marker=track.querySelector('.board-load-sentinel');for(const task of result.items){const wrapper=document.createElement('div');wrapper.innerHTML=boardTaskCard(task);marker?track.insertBefore(wrapper.firstChild,marker):track.appendChild(wrapper.firstChild)}track.dataset.page=String(result.pagination.page);track.dataset.totalPages=String(result.pagination.total_pages);if(result.pagination.page>=result.pagination.total_pages)marker?.remove();else if(marker)marker.textContent='더 보기 ›';bindTaskOpeners(track)}catch(error){if(sentinel){sentinel.textContent='다시 시도';sentinel.onclick=()=>loadMoreBoardTasks(track)}}finally{track.dataset.loading='false'}}
function bindBoardLazyLoads(){document.querySelectorAll('.status-track').forEach(track=>{const maybeLoad=()=>{if(track.scrollLeft+track.clientWidth>=track.scrollWidth-32)loadMoreBoardTasks(track)};track.addEventListener('scroll',maybeLoad,{passive:true});track.querySelector('.board-load-sentinel')?.addEventListener('click',()=>loadMoreBoardTasks(track))})}
function bindUserBoardFilters(){document.querySelectorAll('.status-filter').forEach(button=>button.onclick=()=>{const lane=button.closest('.user-lane');const alreadySelected=button.getAttribute('aria-pressed')==='true';lane.querySelectorAll('.status-rail').forEach(rail=>{rail.hidden=!alreadySelected&&rail.dataset.status!==button.dataset.status});lane.querySelectorAll('.status-filter').forEach(filter=>filter.setAttribute('aria-pressed',String(!alreadySelected&&filter===button)))});document.querySelectorAll('.show-user-all').forEach(button=>button.onclick=()=>{const lane=button.closest('.user-lane');lane.querySelectorAll('.status-rail').forEach(rail=>rail.hidden=false);lane.querySelectorAll('.status-filter').forEach(filter=>filter.setAttribute('aria-pressed','false'))})}
function bindTaskOpeners(scope=document){scope.querySelectorAll('[data-task-id]').forEach(b=>b.onclick=event=>{event.preventDefault();event.stopPropagation();state.selectedTaskId=Number(b.dataset.taskId);state.page='detail';renderDetail().catch(()=>render())})}
async function renderTasks(page=state.taskFilters.page){const filters=state.taskFilters;filters.page=page;const assignees=state.user.role==='ADMIN'?await api('/api/assignees'):[];const load=async()=>{const params=new URLSearchParams({page:String(filters.page),page_size:String(state.user.role==='ADMIN'?1:filters.page_size)});for(const key of ['status','q','received_from','received_to','due_from','due_to','assignee_id'])if(filters[key])params.set(key,filters[key]);return api('/api/tasks?'+params)};const result=await load();const boardUsers=state.user.role==='ADMIN'?await loadUserBoard(assignees):[];state.tasks=result.items;const counts=result.summary;const assigneeControl=state.user.role==='ADMIN'?`<label class="field">처리자<select id="assigneeFilter"><option value="">전체 처리자</option>${assignees.map(u=>`<option value="${u.id}" ${String(u.id)===String(filters.assignee_id)?'selected':''}>${esc(u.name)} (${esc(u.login_id)})</option>`).join('')}</select></label>`:'<p class="muted">내 업무는 생성했거나 처리자로 지정된 업무만 표시됩니다.</p>';const pager=result.pagination;app.innerHTML=shell(`<section class="stats" aria-label="상태별 업무 건수"><div class="stat">접수<br><b>${counts.RECEIVED}건</b></div><div class="stat">진행중<br><b>${counts.IN_PROGRESS}건</b></div><div class="stat">처리<br><b>${counts.COMPLETED}건</b></div></section><section class="panel"><h2>${state.user.role==='ADMIN'?'전체 업무':'내 업무'}</h2><form id="taskFilters" class="grid"><label class="field">검색<input id="search" aria-label="업무 검색" value="${esc(filters.q)}" placeholder="업무 내용, 요청 담당자, 기관 검색"></label><label class="field">상태<select id="statusFilter"><option value="">전체 상태</option>${['RECEIVED','IN_PROGRESS','COMPLETED'].map(s=>`<option value="${s}" ${filters.status===s?'selected':''}>${statusName(s)}</option>`).join('')}</select></label><label class="field">접수일 시작<input id="receivedFrom" type="date" value="${esc(filters.received_from)}"></label><label class="field">접수일 종료<input id="receivedTo" type="date" value="${esc(filters.received_to)}"></label><label class="field">마감일 시작<input id="dueFrom" type="date" value="${esc(filters.due_from)}"></label><label class="field">마감일 종료<input id="dueTo" type="date" value="${esc(filters.due_to)}"></label>${assigneeControl}<label class="field">페이지당 건수<select id="pageSize">${[20,50,100].map(size=>`<option value="${size}" ${filters.page_size===size?'selected':''}>${size}건</option>`).join('')}</select></label><div class="actions"><button class="button primary">적용</button><button type="button" class="button" id="exportTasks">엑셀 다운로드</button><button type="button" class="button" id="resetFilters">초기화</button></div><p class="error full" id="taskFilterError" role="alert" aria-live="polite"></p></form><p class="muted" aria-live="polite">${state.user.role==='ADMIN'?'총 '+pager.total+'건 · 상태별 처음 3건만 표시합니다. 더 보기는 오른쪽으로 넘겨 확인하세요.':'총 '+pager.total+'건 · '+(pager.total_pages||0)+'페이지 중 '+(pager.total?pager.page:0)+'페이지'}</p><div id="taskList">${state.user.role==='ADMIN'?userTaskBoard(boardUsers):(state.tasks.map(taskCard).join('')||'<p class="muted">표시할 업무가 없습니다.</p>')}</div>${state.user.role!=='ADMIN'&&pager.total_pages>1?`<div class="actions pagination" aria-label="업무 목록 페이지"><button class="button" id="previousPage" ${pager.page<=1?'disabled':''}>이전</button><span>${pager.page} / ${pager.total_pages}</span><button class="button" id="nextPage" ${pager.page>=pager.total_pages?'disabled':''}>다음</button></div>`:''}</section>`);document.querySelector('#taskFilters').onsubmit=async event=>{event.preventDefault();const error=document.querySelector('#taskFilterError');error.textContent='';filters.q=document.querySelector('#search').value.trim();filters.status=document.querySelector('#statusFilter').value;filters.received_from=document.querySelector('#receivedFrom').value;filters.received_to=document.querySelector('#receivedTo').value;filters.due_from=document.querySelector('#dueFrom').value;filters.due_to=document.querySelector('#dueTo').value;filters.assignee_id=state.user.role==='ADMIN'?document.querySelector('#assigneeFilter').value:'';filters.page_size=Number(document.querySelector('#pageSize').value);filters.page=1;if(filters.received_from&&filters.received_to&&filters.received_from>filters.received_to){error.textContent='접수일 시작일은 종료일보다 늦을 수 없습니다.';return}try{await renderTasks(1)}catch(cause){error.textContent=cause.message}};document.querySelector('#exportTasks').onclick=async()=>{const error=document.querySelector('#taskFilterError');error.textContent='';try{await downloadTaskExport(filters)}catch(cause){error.textContent=cause.message}};document.querySelector('#resetFilters').onclick=()=>{state.taskFilters={status:'',q:'',received_from:'',received_to:'',due_from:'',due_to:'',assignee_id:'',page:1,page_size:20};renderTasks().catch(cause=>{document.querySelector('#taskFilterError').textContent=cause.message})};if(state.user.role!=='ADMIN'&&pager.total_pages>1){document.querySelector('#previousPage').onclick=()=>renderTasks(Math.max(1,pager.page-1));document.querySelector('#nextPage').onclick=()=>renderTasks(Math.min(pager.total_pages,pager.page+1))}bindTaskOpeners();bindUserBoardFilters();bindBoardLazyLoads();bindShell()}
async function renderStatistics(){const filters=state.statisticsFilters;const admin=state.user.role==='ADMIN';const params=new URLSearchParams();for(const key of ['received_from','received_to','assignee_id'])if(filters[key])params.set(key,filters[key]);const [report,assignees]=await Promise.all([api('/api/statistics?'+params),admin?api('/api/assignees'):Promise.resolve([])]);const assigneeControl=admin?`<label class="field">처리자<select name="assignee_id"><option value="">전체 처리자</option>${assignees.map(u=>`<option value="${u.id}" ${String(filters.assignee_id)===String(u.id)?'selected':''}>${esc(u.name)} (${esc(u.login_id)})</option>`).join('')}</select></label>`:'';const statusCards=['RECEIVED','IN_PROGRESS','COMPLETED'].map(status=>`<div class="stat ${status}">${statusName(status)}<br><b>${report.by_status[status]}건</b></div>`).join('');const userCards=report.by_user.map(row=>`<article class="task ${row.by_status.COMPLETED?'COMPLETED':''}"><h3>${esc(row.name)} ${row.is_active?'':'(비활성)'}</h3><div class="muted">${esc(row.login_id)} · 배정 업무 <b>${row.total}건</b></div><div class="muted">접수 ${row.by_status.RECEIVED} · 진행중 ${row.by_status.IN_PROGRESS} · 처리 ${row.by_status.COMPLETED}</div></article>`).join('')||'<p class="muted">조건에 맞는 처리자 배정 업무가 없습니다.</p>';app.innerHTML=shell(`<section class="panel"><h2>${admin?'운영 통계':'내 업무 통계'}</h2><p class="muted">상태별 건수는 조회 권한이 있는 업무를 기준으로 합니다. ${admin?'처리자를 선택하면 해당 처리자로 지정된 업무만 집계합니다.':'다른 사용자의 업무 또는 처리자 정보는 표시하지 않습니다.'}</p><form id="statisticsFilters" class="grid"><label class="field">접수일 시작<input name="received_from" type="date" value="${esc(filters.received_from)}"></label><label class="field">접수일 종료<input name="received_to" type="date" value="${esc(filters.received_to)}"></label>${assigneeControl}<div class="actions"><button class="button primary">적용</button><button class="button" type="button" id="resetStatistics">초기화</button></div><p class="error full" id="statisticsError" role="alert" aria-live="polite"></p></form></section><section class="stats" aria-label="상태별 업무 통계"><div class="stat">전체 업무<br><b>${report.total}건</b></div>${statusCards}</section><section class="panel" id="userStatistics"><h2>${admin?'처리자별 업무':'내 처리자 배정 업무'}</h2><p class="muted">${esc(report.user_totals_note)}</p>${userCards}</section>`);document.querySelector('#statisticsFilters').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;filters.received_from=form.elements.received_from.value;filters.received_to=form.elements.received_to.value;filters.assignee_id=admin?form.elements.assignee_id.value:'';try{await renderStatistics()}catch(error){document.querySelector('#statisticsError').textContent=error.message}};document.querySelector('#resetStatistics').onclick=()=>{state.statisticsFilters={received_from:'',received_to:'',assignee_id:''};renderStatistics()};bindShell()}
async function renderCalendar(){const tasks=await api('/api/calendar?month='+state.month);const days=daysInMonth(state.month);let cells='';for(let i=1;i<=days;i++){const key=`${state.month}-${String(i).padStart(2,'0')}`,items=tasks.filter(t=>t.received_date===key);cells+=`<div class="day"><b>${i}일</b>${items.slice(0,3).map(t=>`<button type="button" class="tag ${t.status}" data-task-id="${t.id}" aria-label="${i}일 업무 상세 열기: ${esc(t.description.slice(0,20))}">${esc(t.description).slice(0,20)}</button>`).join('')}${items.length>3?`<button type="button" class="more-day" data-day="${key}">+${items.length-3}건</button>`:''}</div>`}app.innerHTML=shell(`<section class="panel"><div class="calendar-title"><button class="button" id="previousMonth" aria-label="이전 달">‹</button><h2>${esc(state.month)} 접수일 캘린더</h2><button class="button" id="nextMonth" aria-label="다음 달">›</button></div><p class="muted">접수일 기준 · 회색 접수 · 파랑 진행중 · 초록 처리.</p><div class="calendar">${cells}</div></section>`);for(const [id,delta] of [['previousMonth',-1],['nextMonth',1]])document.querySelector('#'+id).onclick=()=>{state.month=shiftMonth(state.month,delta);renderCalendar()};document.querySelectorAll('.more-day').forEach(button=>button.onclick=()=>{const items=tasks.filter(t=>t.received_date===button.dataset.day);app.innerHTML=shell(`<section class="panel"><div class="actions"><button class="button" id="backCalendar">캘린더로</button><h2>${esc(button.dataset.day)} 업무</h2></div>${items.map(taskCard).join('')}</section>`);document.querySelector('#backCalendar').onclick=()=>renderCalendar();bindTaskOpeners();bindShell()});bindTaskOpeners();bindShell()}
async function renderCompletedCalendar(){const tasks=await api('/api/completed-calendar?month='+state.month);const days=daysInMonth(state.month);let cells='';for(let i=1;i<=days;i++){const key=`${state.month}-${String(i).padStart(2,'0')}`,items=tasks.filter(t=>t.completed_date===key);cells+=`<div class="day completed-report-day"><b>${i}일</b>${items.slice(0,3).map(t=>`<button type="button" class="tag COMPLETED" data-task-id="${t.id}" aria-label="${i}일 처리 업무 상세 열기: ${esc(t.description.slice(0,20))}">${esc(t.description).slice(0,20)}</button>`).join('')}${items.length>3?`<button type="button" class="more-day" data-completed-day="${key}">+${items.length-3}건</button>`:''}</div>`}app.innerHTML=shell(`<section class="panel"><div class="calendar-title"><button class="button" id="previousReportMonth" aria-label="이전 달">‹</button><h2>${esc(state.month)} 처리일 리포트 캘린더</h2><button class="button" id="nextReportMonth" aria-label="다음 달">›</button></div><p class="muted">처리일 기준 · 처리 완료 업무만 표시합니다.</p><div class="calendar">${cells}</div></section>`);for(const [id,delta] of [['previousReportMonth',-1],['nextReportMonth',1]])document.querySelector('#'+id).onclick=()=>{state.month=shiftMonth(state.month,delta);renderCompletedCalendar()};document.querySelectorAll('[data-completed-day]').forEach(button=>button.onclick=()=>{const items=tasks.filter(t=>t.completed_date===button.dataset.completedDay);app.innerHTML=shell(`<section class="panel"><div class="actions"><button class="button" id="backCompletedCalendar">처리 리포트로</button><h2>${esc(button.dataset.completedDay)} 처리 업무</h2></div>${items.map(taskCard).join('')}</section>`);document.querySelector('#backCompletedCalendar').onclick=()=>renderCompletedCalendar();bindTaskOpeners();bindShell()});bindTaskOpeners();bindShell()}
function contactLabel(c){return `${c.name} · ${c.organization} · ${c.phone}`}
function taskForm(t,assignees,contacts,editing=false){const selected=new Set((t?.assignees||[]).map(a=>a.id));const receivedEditable=!editing||state.user?.role==='ADMIN'||t?.created_by===state.user?.id;return `<form id="taskForm"><div class="grid"><label class="field">처리자(복수 선택)<select id="assignees" multiple required size="5">${assignees.map(u=>`<option value="${u.id}" ${selected.has(u.id)?'selected':''}>${esc(u.name)} (${esc(u.login_id)})</option>`).join('')}</select></label><label class="field">상태<select id="status"><option value="RECEIVED" ${t?.status==='RECEIVED'?'selected':''}>접수</option><option value="IN_PROGRESS" ${t?.status==='IN_PROGRESS'?'selected':''}>진행중</option><option value="COMPLETED" ${t?.status==='COMPLETED'?'selected':''}>처리</option></select></label><label class="field full">기존 요청 담당자 검색<input id="contactSearch" type="search" list="contactSuggestions" autocomplete="off" placeholder="이름 또는 기관명으로 검색" aria-describedby="contactSearchHelp"><datalist id="contactSuggestions">${contacts.map(c=>`<option value="${esc(contactLabel(c))}">`).join('')}</datalist><span class="muted" id="contactSearchHelp">이름 또는 기관명으로 검색한 뒤 목록에서 선택하면 이름·연락처·기관을 자동 입력합니다.</span></label><label class="field">요청 담당자<input id="contactName" required maxlength="50" autocomplete="off" value="${esc(t?.contact?.name||'')}"></label><label class="field">연락처<input id="phone" required maxlength="30" inputmode="tel" value="${esc(t?.contact?.phone||'')}"></label><label class="field">소속 기관<input id="organization" required maxlength="100" list="organizationSuggestions" value="${esc(t?.contact?.organization||'')}"><datalist id="organizationSuggestions"></datalist></label><label class="field">접수일<input id="received" type="date" required ${receivedEditable?'':'disabled aria-describedby="receivedHelp"'} value="${esc(t?.received_date||seoulDate())}">${receivedEditable?'':'<span id="receivedHelp" class="muted">접수일은 업무 생성자 또는 관리자만 수정할 수 있습니다.</span>'}</label><label class="field">마감일(선택)<input id="due" type="date" value="${esc(t?.due_date||'')}"><span class="muted">마감일은 접수일보다 빠를 수 없습니다.</span></label><label class="field">처리일<input id="completed" type="date" value="${esc(t?.completed_date||'')}"></label></div><label class="field">업무 설명<textarea id="description" maxlength="5000" required>${esc(t?.description||'')}</textarea></label><label class="field">이미지(선택, JPG/PNG/WEBP, 최대 5개·파일당 10MB)<input id="taskImages" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><label class="field">문서/동영상(선택, 최대 10개)<input id="taskAttachments" type="file" accept="application/pdf,text/plain,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,video/mp4,video/webm" multiple><span class="muted">문서 PDF/TXT/DOCX/XLSX(각 25MB), 동영상 MP4/WEBM(각 100MB). 비공개 다운로드 전용입니다.</span></label><div class="actions"><button class="button primary">${editing?'변경 저장':'업무 등록'}</button>${editing?'<button type="button" class="button" id="cancelEdit">목록으로</button>':''}</div><p class="error" id="formError" role="alert" aria-live="polite"></p></form>`}
function bindContactAutocomplete(initialContacts){let choices=initialContacts;const search=document.querySelector('#contactSearch'),name=document.querySelector('#contactName'),phoneInput=document.querySelector('#phone'),orgInput=document.querySelector('#organization'),contactList=document.querySelector('#contactSuggestions'),organizationList=document.querySelector('#organizationSuggestions');const renderContactChoices=items=>{contactList.innerHTML=items.map(c=>`<option value="${esc(contactLabel(c))}">`).join('')};const applySelectedContact=()=>{const selected=choices.find(c=>contactLabel(c)===search.value);if(!selected)return false;name.value=selected.name;phoneInput.value=selected.phone;orgInput.value=selected.organization;return true};let contactTimer;search.oninput=()=>{clearTimeout(contactTimer);if(applySelectedContact())return;contactTimer=setTimeout(async()=>{try{const matches=await api('/api/request-contacts?q='+encodeURIComponent(search.value));choices=matches;renderContactChoices(matches);applySelectedContact()}catch(_){/* keep manual request information usable */}},180)};search.onchange=applySelectedContact;let organizationTimer;orgInput.oninput=()=>{clearTimeout(organizationTimer);organizationTimer=setTimeout(async()=>{try{const orgs=await api('/api/organizations?q='+encodeURIComponent(orgInput.value));organizationList.innerHTML=orgs.map(o=>`<option value="${esc(o.name)}">`).join('')}catch(_){/* keep manual entry usable */}},180)}}
function formPayload(){const v=id=>document.querySelector(id).value;return {assignee_ids:[...document.querySelector('#assignees').selectedOptions].map(o=>Number(o.value)),contact:{name:v('#contactName'),phone:v('#phone'),organization:v('#organization')},description:v('#description'),status:v('#status'),received_date:v('#received'),due_date:v('#due')||null,completed_date:v('#completed')||null}}
async function uploadSelectedImages(taskId){const files=[...document.querySelector('#taskImages').files];if(!files.length)return;if(files.length>5)throw new Error('이미지는 최대 5개까지 선택할 수 있습니다.');if(files.some(file=>file.size>10*1024*1024))throw new Error('이미지 파일당 최대 크기는 10MB입니다.');const data=new FormData();files.forEach(file=>data.append('images',file));await api(`/api/tasks/${taskId}/images`,{method:'POST',body:data})}
async function uploadSelectedAttachments(taskId){const files=[...document.querySelector('#taskAttachments').files];if(!files.length)return;if(files.length>10)throw new Error('문서/동영상 첨부는 최대 10개까지 선택할 수 있습니다.');const allowed={'application/pdf':25,'text/plain':25,'application/vnd.openxmlformats-officedocument.wordprocessingml.document':25,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':25,'video/mp4':100,'video/webm':100};for(const file of files){const max=allowed[file.type];if(!max)throw new Error('PDF, TXT, DOCX, XLSX, MP4, WEBM만 첨부할 수 있습니다.');if(file.size>max*1024*1024)throw new Error(`${file.type.startsWith('video/')?'동영상':'문서'} 파일당 최대 크기는 ${max}MB입니다.`)}const data=new FormData();files.forEach(file=>data.append('attachments',file));await api(`/api/tasks/${taskId}/attachments`,{method:'POST',body:data})}
async function bindImageGallery(taskId){for(const image of document.querySelectorAll('[data-private-image]')){try{const response=await fetch(`/api/tasks/${taskId}/images/${image.dataset.privateImage}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error();const url=URL.createObjectURL(await response.blob());image.onload=()=>URL.revokeObjectURL(url);image.src=url}catch(_){image.alt='이미지를 불러올 수 없습니다.'}}document.querySelectorAll('[data-edit-image]').forEach(button=>button.onclick=async()=>{const direction=button.dataset.direction==='COUNTERCLOCKWISE'?'왼쪽':'오른쪽';if(!confirm(`이미지를 ${direction}으로 90° 회전하시겠습니까? 원본은 비공개 편집 이력으로 보존됩니다.`))return;button.disabled=true;try{await api(`/api/tasks/${taskId}/images/${button.dataset.editImage}/edit`,{method:'POST',body:JSON.stringify({direction:button.dataset.direction})});renderDetail()}catch(err){alert(err.message);button.disabled=false}});document.querySelectorAll('[data-delete-image]').forEach(button=>button.onclick=async()=>{if(!confirm('이 이미지를 삭제하시겠습니까? 편집 이력의 비공개 원본도 함께 삭제됩니다.'))return;try{await api(`/api/tasks/${taskId}/images/${button.dataset.deleteImage}`,{method:'DELETE'});renderDetail()}catch(err){alert(err.message)}})}
function bindAttachmentList(taskId){document.querySelectorAll('[data-download-attachment]').forEach(button=>button.onclick=async()=>{try{const response=await fetch(`/api/tasks/${taskId}/attachments/${button.dataset.downloadAttachment}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error('첨부 파일을 내려받을 수 없습니다.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=button.dataset.filename||'attachment';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){alert(err.message)}});document.querySelectorAll('[data-delete-attachment]').forEach(button=>button.onclick=async()=>{if(!confirm('이 첨부 파일을 삭제하시겠습니까?'))return;try{await api(`/api/tasks/${taskId}/attachments/${button.dataset.deleteAttachment}`,{method:'DELETE'});renderDetail()}catch(err){alert(err.message)}})}
async function renderNew(){const [assignees,contacts]=await Promise.all([api('/api/assignees'),api('/api/request-contacts')]);app.innerHTML=shell(`<section class="panel"><h2>업무 등록</h2>${taskForm(null,assignees,contacts)}</section>`);document.querySelector('#taskForm').onsubmit=async e=>{e.preventDefault();try{const created=await api('/api/tasks',{method:'POST',body:JSON.stringify(formPayload())});try{await uploadSelectedImages(created.id);await uploadSelectedAttachments(created.id)}catch(err){state.selectedTaskId=created.id;state.page='detail';await render();alert(`업무는 저장되었으나 일부 첨부 업로드에 실패했습니다: ${err.message}`);return}state.page='tasks';render()}catch(err){document.querySelector('#formError').textContent=err.message}};bindContactAutocomplete(contacts);bindShell()}
function historyRow(h){const action=h.action==='TASK_CREATED'?'업무 등록':h.action==='TASK_UPDATED'?'업무 수정':h.action==='TASK_DELETED'?'업무 삭제':h.action==='TASK_IMAGE_UPLOADED'?'이미지 첨부':h.action==='TASK_IMAGE_EDITED'?'이미지 90° 회전':h.action==='TASK_IMAGE_DELETED'?'이미지 삭제':h.action==='TASK_ATTACHMENT_UPLOADED'?'문서/동영상 첨부':h.action==='TASK_ATTACHMENT_DELETED'?'문서/동영상 첨부 삭제':h.action;return `<li><b>${action}</b> · ${esc(h.actor_name||'알 수 없음')}<div class="muted">${esc(formatTimestamp(h.created_at))} · ${h.changed_fields.length?`변경: ${esc(h.changed_fields.join(', '))}`:'변경 항목 없음'}</div></li>`}
async function renderDetail(){try{const [task,assignees,contacts,history]=await Promise.all([api(`/api/tasks/${state.selectedTaskId}`),api('/api/assignees'),api('/api/request-contacts'),api(`/api/tasks/${state.selectedTaskId}/history`)]);app.innerHTML=shell(`<section class="panel"><div class="actions title-actions"><button class="button" id="backTasks">목록으로</button><h2>업무 상세 및 수정</h2></div><p class="muted">생성자 ${esc(task.created_by_name)} · 생성 ${esc(formatTimestamp(task.created_at))} · 최종 수정 ${esc(formatTimestamp(task.updated_at))}</p>${taskForm(task,assignees,contacts,true)}<section class="image-section" aria-labelledby="imageHeading"><h3 id="imageHeading">첨부 이미지</h3><p class="muted">이미지는 이 업무에 접근 가능한 사용자만 볼 수 있습니다.</p><div class="image-grid">${task.images.length?task.images.map(image=>`<figure class="image-card"><img data-private-image="${image.id}" alt="첨부 이미지: ${esc(image.original_filename)}"><figcaption>${esc(image.original_filename)} · ${Math.ceil(image.size_bytes/1024)}KB <div class="actions image-actions"><button type="button" class="button" data-edit-image="${image.id}" data-direction="COUNTERCLOCKWISE">↶ 왼쪽 90°</button><button type="button" class="button" data-edit-image="${image.id}" data-direction="CLOCKWISE">↷ 오른쪽 90°</button><button type="button" class="button danger" data-delete-image="${image.id}">이미지 삭제</button></div><span class="muted">회전 편집은 비공개 원본을 보존합니다.</span></figcaption></figure>`).join(''):'<p class="muted">첨부된 이미지가 없습니다.</p>'}</div></section><section class="attachment-section" aria-labelledby="attachmentHeading"><h3 id="attachmentHeading">문서/동영상 첨부</h3><p class="muted">이 업무에 접근 가능한 사용자만 내려받을 수 있으며, 브라우저 미리보기 대신 비공개 다운로드로 제공합니다. 이미지 편집은 90° 회전만 제공하며 원본은 비공개 편집 이력으로 보존됩니다.</p><div class="attachment-list">${task.attachments.length?task.attachments.map(attachment=>`<article class="attachment-card"><b>${esc(attachment.attachment_type==='VIDEO'?'동영상':'문서')}</b> · ${esc(attachment.original_filename)}<div class="muted">${esc(attachment.mime_type)} · ${Math.ceil(attachment.size_bytes/1024)}KB</div><div class="actions"><button type="button" class="button" data-download-attachment="${attachment.id}" data-filename="${esc(attachment.original_filename)}">내려받기</button><button type="button" class="button danger" data-delete-attachment="${attachment.id}">첨부 삭제</button></div></article>`).join(''):'<p class="muted">첨부된 문서 또는 동영상이 없습니다.</p>'}</div></section>${state.user.role==='ADMIN'?'<div class="delete-zone"><button class="button danger" id="deleteTask">업무 삭제</button><p class="muted">삭제하면 목록에서 숨겨지며 관리자 기록에는 보존됩니다.</p></div>':''}</section><section class="panel"><h2>변경 이력</h2><ol class="history">${history.map(historyRow).join('')||'<li class="muted">변경 이력이 없습니다.</li>'}</ol></section>`);const returnToTasks=()=>{state.page='tasks';render()};document.querySelector('#backTasks').onclick=returnToTasks;document.querySelector('#cancelEdit').onclick=returnToTasks;document.querySelector('#taskForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify(formPayload())});try{await uploadSelectedImages(task.id);await uploadSelectedAttachments(task.id)}catch(err){await renderDetail();alert(`업무 정보는 저장되었으나 일부 첨부 업로드에 실패했습니다: ${err.message}`);return}renderDetail()}catch(err){document.querySelector('#formError').textContent=err.message}};if(state.user.role==='ADMIN')document.querySelector('#deleteTask').onclick=async()=>{if(!confirm('이 업무를 삭제하시겠습니까? 삭제 후 목록과 캘린더에서 보이지 않습니다.'))return;try{await api(`/api/tasks/${task.id}`,{method:'DELETE'});state.page='tasks';render()}catch(err){alert(err.message)}};bindContactAutocomplete(contacts);bindImageGallery(task.id);bindAttachmentList(task.id);bindShell()}catch(err){app.innerHTML=shell(`<section class="panel"><h2>업무를 열 수 없습니다</h2><p class="error">${esc(err.message)}</p><button class="button" id="backTasks">목록으로</button></section>`);document.querySelector('#backTasks').onclick=()=>{state.page='tasks';render()};bindShell()}}
function formatTimestamp(value){if(!value)return '-';const parsed=new Date(value);if(Number.isNaN(parsed.getTime()))return value;return new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short',hour12:false}).format(parsed)}
function userEditor(u){const active=Boolean(u.is_active);return `<form class="user-editor" data-user-form data-user-id="${u.id}" data-active="${active}"><fieldset><legend><span>${esc(u.name)}</span><span class="user-login-id">${esc(u.login_id)}</span></legend><div class="user-editor-grid"><label class="field">이름<input name="name" required maxlength="50" value="${esc(u.name)}"></label><label class="field">역할<select name="role" aria-label="${esc(u.name)} 계정 역할"><option value="MEMBER" ${u.role==='MEMBER'?'selected':''}>일반 이용자</option><option value="ADMIN" ${u.role==='ADMIN'?'selected':''}>관리자</option></select></label></div><label class="field user-password-field">임시 비밀번호 재발급 <span class="optional">선택</span><input name="password" type="password" minlength="8" maxlength="200" autocomplete="new-password" aria-describedby="resetHelp-${u.id}"><span class="field-help" id="resetHelp-${u.id}">입력하면 다음 로그인 때 비밀번호 변경이 필요합니다.</span></label><div class="user-editor-footer"><label class="checkbox-field"><input name="is_active" type="checkbox" ${active?'checked':''}><span>활성 계정</span></label><button class="button" type="submit">변경 저장</button><span class="user-editor-meta">생성 ${esc(formatTimestamp(u.created_at))} · 수정 ${esc(formatTimestamp(u.updated_at))}${u.must_change_password?' · 비밀번호 변경 대기':''}</span></div><p class="error" data-user-error role="alert" aria-live="polite"></p></fieldset></form>`}
async function renderUsers(){const users=await api('/api/admin/users');app.innerHTML=shell(`<section class="panel"><h2>사용자 관리</h2><p class="muted">계정의 이름, 역할, 활성 상태를 관리하고 필요하면 임시 비밀번호를 재발급할 수 있습니다. 마지막 활성 관리자 계정은 역할 변경 또는 비활성화할 수 없습니다.</p><form id="userForm" class="grid"><label class="field">이름<input id="uname" required maxlength="50"></label><label class="field">로그인 ID<input id="uid" required maxlength="50" autocomplete="username"></label><label class="field">임시 비밀번호<input id="upw" type="password" minlength="8" maxlength="200" required autocomplete="new-password"></label><label class="field">역할<select id="urole"><option value="MEMBER">일반 이용자</option><option value="ADMIN">관리자</option></select></label><div class="actions"><button class="button primary">사용자 추가</button></div><p class="error full" id="userFormError" role="alert" aria-live="polite"></p></form></section><section class="panel"><h2>등록 사용자</h2>${users.map(userEditor).join('')||'<p class="muted">등록된 사용자가 없습니다.</p>'}</section>`);const createForm=document.querySelector('#userForm');createForm.onsubmit=async e=>{e.preventDefault();const error=document.querySelector('#userFormError');error.textContent='';try{await api('/api/admin/users',{method:'POST',body:JSON.stringify({name:createForm.elements.uname.value,login_id:createForm.elements.uid.value,temporary_password:createForm.elements.upw.value,role:createForm.elements.urole.value})});await renderUsers()}catch(err){error.textContent=err.message}};document.querySelectorAll('[data-user-form]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const error=form.querySelector('[data-user-error]');error.textContent='';const password=form.elements.password.value;const nextActive=form.elements.is_active.checked;if(form.dataset.active==='true'&&!nextActive&&!confirm('이 계정을 비활성화하시겠습니까? 기존 업무 이력은 유지됩니다.'))return;const payload={name:form.elements.name.value,role:form.elements.role.value,is_active:nextActive};if(password)payload.password=password;try{await api('/api/admin/users/'+form.dataset.userId,{method:'PATCH',body:JSON.stringify(payload)});const currentId=state.user?.id;if(Number(form.dataset.userId)===currentId&&(password||payload.role!==state.user.role||!nextActive)){localStorage.removeItem('token');state.token='';state.user=null;render();return}if(Number(form.dataset.userId)===currentId)state.user.name=payload.name;await renderUsers()}catch(err){error.textContent=err.message}});bindShell()}
function masterOrgRow(o){return `<form class="master-row master-org-row" data-org="${o.id}"><label class="field">기관명<input name="name" maxlength="100" required value="${esc(o.name)}"></label><label class="checkbox-field"><input name="active" type="checkbox" ${o.is_active?'checked':''}><span>사용</span></label><div class="master-row-actions"><button type="submit" class="button">저장</button><span class="master-row-meta">수정 ${esc(formatTimestamp(o.updated_at))}</span></div></form>`}
function masterContactRow(c,orgs){return `<form class="master-row master-contact-row" data-contact="${c.id}"><label class="field">이름<input name="name" maxlength="50" required value="${esc(c.name)}"></label><label class="field">연락처<input name="phone" maxlength="30" required value="${esc(c.phone)}"></label><label class="field">기관<select name="organization_id">${orgs.map(o=>`<option value="${o.id}" ${o.id===c.organization_id?'selected':''}>${esc(o.name)}${o.is_active?'':' (중지)'}</option>`).join('')}</select></label><label class="checkbox-field"><input name="active" type="checkbox" ${c.is_active?'checked':''}><span>사용</span></label><div class="master-row-actions"><button type="submit" class="button">저장</button>${c.updated_at?`<span class="master-row-meta">수정 ${esc(formatTimestamp(c.updated_at))}</span>`:''}</div></form>`}
async function renderMasters(){const [orgs,contacts]=await Promise.all([api('/api/admin/organizations'),api('/api/admin/request-contacts')]);app.innerHTML=shell(`<section class="panel"><h2>요청 정보 관리</h2><p class="muted">관리자만 마스터 원본을 수정하거나 사용 중지할 수 있습니다. 사용 중지 항목은 새 업무 자동완성에서 제외됩니다.</p><div class="actions"><input id="masterSearch" placeholder="기관, 담당자, 연락처 검색" aria-label="요청 정보 검색"><button class="button" id="masterSearchButton">검색</button></div><p class="error" id="masterError" role="alert" aria-live="polite"></p></section><section class="panel"><h2>기관</h2><form id="newOrg" class="actions"><label>새 기관명 <input id="newOrgName" maxlength="100" required></label><button class="button primary">기관 추가</button></form><div id="orgRows">${orgs.map(masterOrgRow).join('')||'<p class="muted">기관이 없습니다.</p>'}</div></section><section class="panel"><h2>요청 담당자</h2><div id="contactRows">${contacts.map(c=>masterContactRow(c,orgs)).join('')||'<p class="muted">요청 담당자가 없습니다.</p>'}</div></section>`);newOrg.onsubmit=async e=>{e.preventDefault();try{await api('/api/organizations',{method:'POST',body:JSON.stringify({name:newOrgName.value})});renderMasters()}catch(err){document.querySelector('#masterError').textContent=err.message}};document.querySelectorAll('[data-org]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/organizations/'+f.dataset.org,{method:'PATCH',body:JSON.stringify({name:f.elements.name.value,is_active:f.elements.active.checked})});renderMasters()}catch(err){document.querySelector('#masterError').textContent=err.message}});document.querySelectorAll('[data-contact]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/request-contacts/'+f.dataset.contact,{method:'PATCH',body:JSON.stringify({name:f.elements.name.value,phone:f.elements.phone.value,organization_id:Number(f.elements.organization_id.value),is_active:f.elements.active.checked})});renderMasters()}catch(err){document.querySelector('#masterError').textContent=err.message}});masterSearchButton.onclick=async()=>{try{const q=encodeURIComponent(masterSearch.value);const [nextOrgs,nextContacts]=await Promise.all([api('/api/admin/organizations?q='+q),api('/api/admin/request-contacts?q='+q)]);orgRows.innerHTML=nextOrgs.map(masterOrgRow).join('')||'<p class="muted">기관이 없습니다.</p>';contactRows.innerHTML=nextContacts.map(c=>masterContactRow(c,orgs)).join('')||'<p class="muted">요청 담당자가 없습니다.</p>';bindMasterSaveAfterSearch()}catch(err){document.querySelector('#masterError').textContent=err.message}};bindShell()}
function bindMasterSaveAfterSearch(){document.querySelectorAll('[data-org]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/organizations/'+f.dataset.org,{method:'PATCH',body:JSON.stringify({name:f.elements.name.value,is_active:f.elements.active.checked})});renderMasters()}catch(err){document.querySelector('#masterError').textContent=err.message}});document.querySelectorAll('[data-contact]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/request-contacts/'+f.dataset.contact,{method:'PATCH',body:JSON.stringify({name:f.elements.name.value,phone:f.elements.phone.value,organization_id:Number(f.elements.organization_id.value),is_active:f.elements.active.checked})});renderMasters()}catch(err){document.querySelector('#masterError').textContent=err.message}})}
const auditActionName=action=>({LOGIN_SUCCESS:'로그인 성공',LOGIN_FAILED:'로그인 실패',PASSWORD_CHANGED:'비밀번호 변경',PASSWORD_HASH_UPGRADED:'비밀번호 해시 전환',USER_CREATED:'사용자 생성',USER_UPDATED:'사용자 수정',ORGANIZATION_CREATED:'기관 생성',ORGANIZATION_UPDATED:'기관 수정',REQUEST_CONTACT_CREATED:'요청 담당자 생성',REQUEST_CONTACT_UPDATED:'요청 담당자 수정',TASK_CREATED:'업무 등록',TASK_UPDATED:'업무 수정',TASK_DELETED:'업무 삭제',TASK_IMAGE_UPLOADED:'이미지 첨부',TASK_IMAGE_EDITED:'이미지 90° 회전',TASK_IMAGE_DELETED:'이미지 삭제',TASK_ATTACHMENT_UPLOADED:'문서/동영상 첨부',TASK_ATTACHMENT_DELETED:'문서/동영상 첨부 삭제',TASKS_EXPORTED:'엑셀 업무 내보내기',NOTIFICATION_PREFERENCES_UPDATED:'알림 설정 변경'}[action]||action);
function auditChange(label,value){if(value===null||value===undefined)return '';return `<details><summary>${label} 값</summary><pre>${esc(JSON.stringify(value,null,2))}</pre></details>`}
function auditLogCard(log){return `<article class="task audit-entry"><b>${esc(auditActionName(log.action))}</b> <span class="muted">(${esc(log.action)})</span> · ${esc(log.actor_name||'알 수 없음')}<div class="muted">${esc(log.target_type)} #${esc(log.target_id)} · ${esc(log.created_at)}${log.ip_address?` · IP ${esc(log.ip_address)}`:''}</div>${auditChange('변경 전',log.before)}${auditChange('변경 후',log.after)}</article>`}
async function renderAudit(){const filters={action:'',actor_user_id:'',created_from:'',created_to:''};const [initialLogs,users]=await Promise.all([api('/api/admin/audit-logs'),api('/api/admin/users')]);const actions=['LOGIN_SUCCESS','LOGIN_FAILED','PASSWORD_CHANGED','PASSWORD_HASH_UPGRADED','USER_CREATED','USER_UPDATED','ORGANIZATION_CREATED','ORGANIZATION_UPDATED','REQUEST_CONTACT_CREATED','REQUEST_CONTACT_UPDATED','TASK_CREATED','TASK_UPDATED','TASK_DELETED','TASK_IMAGE_UPLOADED','TASK_IMAGE_EDITED','TASK_IMAGE_DELETED','TASK_ATTACHMENT_UPLOADED','TASK_ATTACHMENT_DELETED','TASKS_EXPORTED'];const draw=logs=>{app.innerHTML=shell(`<section class="panel"><h2>감사 로그</h2><p class="muted">이벤트 유형, 실행자, 기간으로 최대 최근 100건의 감사 기록을 필터링합니다. 변경 전·후 값은 펼쳐서 확인할 수 있으며 민감 값은 표시되지 않습니다.</p><form id="auditFilters" class="grid"><label class="field">이벤트 유형<select name="action"><option value="">전체 이벤트</option>${actions.map(action=>`<option value="${action}" ${filters.action===action?'selected':''}>${esc(auditActionName(action))} (${action})</option>`).join('')}</select></label><label class="field">실행자<select name="actor_user_id"><option value="">전체 실행자</option>${users.map(user=>`<option value="${user.id}" ${String(user.id)===String(filters.actor_user_id)?'selected':''}>${esc(user.name)} (${esc(user.login_id)})</option>`).join('')}</select></label><label class="field">시작일<input name="created_from" type="date" value="${esc(filters.created_from)}"></label><label class="field">종료일<input name="created_to" type="date" value="${esc(filters.created_to)}"></label><div class="actions"><button class="button primary">필터 적용</button><button type="button" class="button" id="resetAuditFilters">초기화</button></div><p class="error full" id="auditFilterError" role="alert" aria-live="polite"></p></form></section><section class="panel"><h2>기록 ${logs.length}건</h2><div id="auditResults">${logs.map(auditLogCard).join('')||'<p class="muted">조건에 맞는 로그가 없습니다.</p>'}</div></section>`);document.querySelector('#auditFilters').onsubmit=async event=>{event.preventDefault();const error=document.querySelector('#auditFilterError');error.textContent='';const form=event.currentTarget;filters.action=form.elements.action.value;filters.actor_user_id=form.elements.actor_user_id.value;filters.created_from=form.elements.created_from.value;filters.created_to=form.elements.created_to.value;const params=new URLSearchParams();for(const key of Object.keys(filters))if(filters[key])params.set(key,filters[key]);try{draw(await api('/api/admin/audit-logs?'+params))}catch(err){error.textContent=err.message}};document.querySelector('#resetAuditFilters').onclick=()=>{Object.assign(filters,{action:'',actor_user_id:'',created_from:'',created_to:''});draw(initialLogs)};bindShell()};draw(initialLogs)}
async function renderNotifications(){const [outbox,preferences]=await Promise.all([api('/api/notifications'),api('/api/me/notification-preferences')]);const kindName={DUE_SOON:'마감 임박',DUE_TODAY:'오늘 마감',OVERDUE:'마감 지남'};const cards=outbox.items.map(item=>`<article class="task notification ${item.is_read?'read':''}"><h3>${esc(kindName[item.kind]||item.kind)} · ${esc(item.due_date)}</h3><div>${esc(item.message)}</div><div class="muted">업무: ${esc(item.description)} · ${item.is_read?'읽음':'읽지 않음'}</div><div class="actions"><button type="button" class="button notification-open" data-task-id="${item.task_id}">업무 열기</button>${item.is_read?'':'<button type="button" class="button" data-read-notification="'+item.id+'">읽음 처리</button>'}</div></article>`).join('')||'<p class="muted">현재 표시할 마감 알림이 없습니다.</p>';app.innerHTML=shell(`<section class="panel"><h2>마감 알림</h2><p class="muted">알림은 이 화면 안의 안전한 로컬 알림함에만 저장됩니다. 이메일·문자·메신저는 전송하지 않습니다.</p><form id="notificationPreferences" class="grid"><label class="checkbox-field"><input name="due_soon_enabled" type="checkbox" ${preferences.due_soon_enabled?'checked':''}> 오늘/3일 이내 마감 알림</label><label class="checkbox-field"><input name="overdue_enabled" type="checkbox" ${preferences.overdue_enabled?'checked':''}> 마감 지난 업무 알림</label><div class="actions"><button class="button primary">알림 설정 저장</button></div><p class="error full" id="notificationError" role="alert" aria-live="polite"></p></form></section><section class="panel"><h2>내 알림 ${outbox.pagination.total}건</h2><div id="notificationList">${cards}</div></section>`);document.querySelector('#notificationPreferences').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;try{await api('/api/me/notification-preferences',{method:'PATCH',body:JSON.stringify({due_soon_enabled:form.elements.due_soon_enabled.checked,overdue_enabled:form.elements.overdue_enabled.checked})});renderNotifications()}catch(error){document.querySelector('#notificationError').textContent=error.message}};document.querySelectorAll('[data-read-notification]').forEach(button=>button.onclick=async()=>{try{await api('/api/notifications/'+button.dataset.readNotification+'/read',{method:'POST'});renderNotifications()}catch(error){document.querySelector('#notificationError').textContent=error.message}});bindTaskOpeners();bindUserBoardFilters();bindBoardLazyLoads();bindShell()}
function renderPasswordChange(){app.innerHTML=`<form class="panel login" id="passwordChange"><h1>비밀번호 변경</h1><p class="muted">최초 로그인입니다. 업무를 이용하려면 임시 비밀번호를 새 비밀번호로 변경해야 합니다.</p><label class="field">현재 비밀번호<input id="currentPassword" type="password" required autocomplete="current-password"></label><label class="field">새 비밀번호<input id="newPassword" type="password" minlength="8" required autocomplete="new-password"></label><label class="field">새 비밀번호 확인<input id="newPasswordConfirm" type="password" minlength="8" required autocomplete="new-password"></label><div class="actions"><button class="button primary">비밀번호 변경</button><button class="button" type="button" id="passwordLogout">로그아웃</button></div><p class="error" id="passwordError" role="alert"></p></form>`;passwordChange.onsubmit=async e=>{e.preventDefault();if(newPassword.value!==newPasswordConfirm.value){passwordError.textContent='새 비밀번호 확인이 일치하지 않습니다.';return}try{await api('/api/me/password',{method:'POST',body:JSON.stringify({current_password:currentPassword.value,new_password:newPassword.value})});state.user=await api('/api/me');render()}catch(err){passwordError.textContent=err.message}};passwordLogout.onclick=async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('token');state.token='';state.user=null;render()}}
async function render(){if(!state.token){app.innerHTML=`<form class="panel login" id="login"><h1>공유 업무 캘린더</h1><label class="field">로그인 ID<input id="loginId" required></label><label class="field">비밀번호<input id="password" type="password" required></label><div class="actions"><button class="button primary">로그인</button></div><p class="error" id="loginError" role="alert"></p></form>`;login.onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({login_id:loginId.value,password:password.value})});state.token=d.token;state.user=d.user;localStorage.token=d.token;render()}catch(err){loginError.textContent=err.message}};return}try{state.user=await api('/api/me');if(state.user.must_change_password)return renderPasswordChange();if(state.page==='tasks')return renderTasks();if(state.page==='calendar')return renderCalendar();if(state.page==='completedCalendar')return renderCompletedCalendar();if(state.page==='statistics')return renderStatistics();if(state.page==='notifications')return renderNotifications();if(state.page==='new')return renderNew();if(state.page==='detail')return renderDetail();if(state.page==='users')return renderUsers();if(state.page==='masters')return renderMasters();if(state.page==='audit')return renderAudit()}catch(_){localStorage.removeItem('token');state.token='';render()}}
render();
